cases.bad:
const caretRange = document.caretRangeFromPoint(x, y);
if (!caretRange) { dismiss(); return; }
const ctx = extractSentenceContext(caretRange.startContainer, caretRange.startOffset);
if (!ctx) { dismiss(); return; } // ← space offset → ctx null → dismiss
// Click on space between 'hello' and 'world' → popup dismissed → "lúc được lúc không"

cases.good:
const resolved = resolveWordAtPoint(x, y, { getCaretRange });
if (!resolved) { dismiss(); return; }
// resolveWordAtPoint: (1) caret on word → direct; (2) caret on space → scan left/right for nearest word char; (3) caret null → geometry fallback
// Click on space between 'hello' and 'world' → char-scan finds 'hello' (tie → left) → popup shows 'hello'

cases.bad:
const wordRange = createWordRange(textNode, offset, ctx);
if (!isPointOverRange(x, y, wordRange)) { dismiss(); return; } // ← 1px off → dismiss
// Word-wrap boundary: word rect starts 1px left of click → gate fails → popup dismissed

cases.good:
// For clicks (intentional): trust the resolution, skip the geometry gate
const resolved = resolveWordAtPoint(x, y, { getCaretRange });
if (!resolved) { dismiss(); return; }
// For hover (passive): keep the gate as a fallback trigger, not a hard dismiss
if (!lenient && !isPointOverRange(x, y, resolved.range)) { dismiss(); return; }
